<?php
require_once __DIR__ . '/../includes/auth.php'; require_role(['admin']);
$status = get_str('status', 'all'); $allowed = ['all', 'approved', 'pending', 'rejected', 'banned']; if (!in_array($status, $allowed, true)) $status = 'all';
$where = $status === 'all' ? '1=1' : 'account_status = ?'; $params = $status === 'all' ? [] : [$status];
$count = $pdo->prepare("SELECT COUNT(*) FROM users WHERE role <> 'admin' AND $where"); $count->execute($params); $pager = paginate((int) $count->fetchColumn());
$stmt = $pdo->prepare("SELECT id, full_name, email, roll_no, role, account_status, strike_count, created_at FROM users WHERE role <> 'admin' AND $where ORDER BY created_at DESC LIMIT ? OFFSET ?");
foreach ($params as $i => $p) $stmt->bindValue($i + 1, $p); $stmt->bindValue(count($params) + 1, $pager['per_page'], PDO::PARAM_INT); $stmt->bindValue(count($params) + 2, $pager['offset'], PDO::PARAM_INT); $stmt->execute(); $users = $stmt->fetchAll();
$page_title = 'Users'; require __DIR__ . '/../includes/header.php';
?>
<div class="page-header"><div><h1>Users</h1><p class="muted">Review member accounts and suspensions.</p></div><form method="get"><label for="status" class="sr-only">Status</label><select id="status" name="status" onchange="this.form.submit()"><?php foreach ($allowed as $item): ?><option value="<?= e($item) ?>"<?= $status === $item ? ' selected' : '' ?>><?= e(ucfirst($item)) ?></option><?php endforeach; ?></select></form></div>
<div class="table-wrap"><table class="table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Strikes</th><th>Joined</th><th>Actions</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?= e($user['full_name']) ?><br><span class="muted"><?= e($user['email']) ?></span></td><td><?= e(ucfirst($user['role'])) ?></td><td><?= status_badge($user['account_status']) ?></td><td><?= (int) $user['strike_count'] ?></td><td><?= e(format_date($user['created_at'])) ?></td><td class="table-actions"><?php if ($user['account_status'] === 'banned'): ?><form method="post" action="<?= e(url('actions/admin/unban_user.php')) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int) $user['id'] ?>"><button class="btn btn-sm" type="submit">Unban</button></form><?php else: ?><form method="post" action="<?= e(url('actions/admin/ban_user.php')) ?>" class="inline-form" data-confirm="Ban this user?"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int) $user['id'] ?>"><button class="btn btn-sm btn-danger" type="submit">Ban</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?= render_pagination($pager) ?>
<?php require __DIR__ . '/../includes/footer.php'; ?>
